init:
root => {
    const bar = root.querySelector('[data-hhbar]'), box = root.querySelector('[data-hhscroll]');
    let last = 0;
    box.addEventListener('scroll', () => {
      const y = box.scrollTop;
      if (y > last + 2) bar.classList.add('up');
      else if (y < last - 2) bar.classList.remove('up');
      last = y;
    });
  }
